fn max_range_nearly_can_use(champ: &Entity, target: &Entity, tick: usize) -> u64 {
  let mut range: u64 = 0;                                   // battle.rs:2398

  // == 슬롯1: 평타 이펙트 champ+0x490 ==  battle.rs:2399~2405
  if let Some(e) = champ.attack_effect.as_ref() {           // e+0x30 != -1
    if e.casting_target(+0x28).check(champ, target) {        // 2402
      let cd = champ.attack_cooldown();                      // entity.rs:1747, match champ[0x68]
      //   kind 0,3   -> 0   (쿨다운 없음 — LLVM이 `0 > tick == false` 로 접어 비교가 사라짐)
      //   kind 1     -> champ[0xb8]
      //   kind 2     -> champ[0x110]   (1758)
      //   kind 4,7   -> champ[0xe8]    (1750)
      //   kind 5,6   -> champ[0x1f0]   (1760)
      //   kind 8,13  -> champ[0xb0]    (1753)
      //   kind 9     -> champ[0xc8]    (1754)
      //   kind 10    -> champ[0xf0]    (1755)
      //   kind 11    -> champ[0xd8]    (1756)
      //   kind 12    -> champ[0xd0]    (1757)
      if !(cd > tick) {                                      // = cd <= tick 이면 후보
        range = range.max( e.range(champ)                    // 2403
                         + e.range_adjust(champ, target)
                         + champ.radius() + target.radius() );
      }
    }
  }

  // == 슬롯2: 스킬 이펙트 champ+0x4c8 ==  battle.rs:2407~2412
  if let Some(e) = champ.skill_effect.as_ref() {
    if e.casting_target.check(champ, target) {                // 2409
      let cd = if champ[0x68] == 13 { champ[0xb8] } else { 0 };   // entity.rs:1775
      if !(cd > tick) {
        range = range.max( e.range(champ) + e.range_adjust(champ,target)
                         + champ.radius() + target.radius() );   // 2410
      }
    }
  }

  // == 슬롯3: 스킬2 champ+0x500 ==  battle.rs:2414~2419
  //  entity.rs:1693 -> level(0x5c8) > 2 일 때만 실제 필드, 아니면 정적 None(@anon....40, 태그 -1)
  if let Some(e) = champ.skill2_effect() {
    if e.casting_target.check(champ, target) {                // 2416
      let cd = if champ[0x68] == 13 { champ[0xc0] } else { 0 };   // entity.rs:1790
      if !(cd > tick) {
        range = range.max( 위와 동일한 4항 합 );                  // 2417
      }
    }
  }

  // == 슬롯4: 궁극기 champ+0x538 ==  battle.rs:2421~2426
  //  entity.rs:1701 -> level > 4 일 때만 실제 필드, 아니면 정적 None
  if let Some(e) = champ.ult_effect() {
    if e.casting_target.check(champ, target) {                // 2423
      let cd = if champ[0x68] == 13 { champ[0xc8] } else { 0 };   // entity.rs:1805
      if !(cd > tick) {
        range = range.max( 위와 동일한 4항 합 );                  // 2424
      }
    }
  }

  range                                                        // battle.rs:2429
}

-- 인라인된 보조 함수 --
Effect::range(&self, caster) -> u64            // effect.rs:25~26
  = caster[0x438] + self[+0x10] + self[+0x18] * (caster.level[0x5c8] - 1)

Entity::radius(&self) -> u64                   // entity.rs:1509~1516
  let m = self[0x470] as i32;
  if m == 0 { self[0x680] } else { self[0x680] * (m + 100) / 100 }

※ 최종 사거리 합산 순서(IR 그대로):
   caster[0x438] + eff[0x10] + eff[0x18]*(lv-1) + range_adjust + champ.radius() + target.radius()
※ 슬롯1은 range 초기값이 0 이라 max() 가 접혀 그냥 대입이 됐고, 슬롯2~4 는 llvm.umax.i64 로 남아 있다.
※ 세 게이트가 AND 로 걸린다: (1)슬롯이 Some (2)CastingTarget::check 통과 (3)잔여쿨 <= tick. 하나라도 실패하면 그 슬롯은 건너뛰고 누적값을 그대로 넘긴다.
※ 반환값은 '지금 실제로 쓸 수 있는 사거리'가 아니라 'tick 안에 쓸 수 있게 되는 것까지 포함한 최대 사거리'다 — 함수명의 nearly 가 그 뜻.
